PRICES = {'apple': 0.5, 'bread': 2.25, 'milk': 1.1}


def total(basket):
    amount = sum(PRICES[name] * int(count) for name, count in basket)
    if amount > 20:
        amount *= 0.9
    return round(amount, 2)

