import unittest

from shop.prices import total


class TestTotal(unittest.TestCase):
    def test_a_basket_adds_up(self):
        self.assertEqual(total([('apple', '2'), ('milk', '1')]), 2.1)

    def test_a_big_basket_gets_ten_percent_off(self):
        self.assertEqual(total([('bread', '10')]), 20.25)
